W, H = 170, 46


def _svg(i):
    pos = {k: xy for k, _, _, _, xy in STATUSES}
    cat = {k: c for k, _, c, _, _ in STATUSES}
    name = {k: n for k, n, _, _, _ in STATUSES}
    out = ['<svg class="wf" viewBox="0 0 1050 500" role="img" aria-labelledby="wf-t"><title id="wf-t">Customer Discovery workflow</title>',
           '<defs><marker id="ah" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse">'
           '<path d="M0 0L10 5L0 10z" class="ahp"/></marker></defs>']

    def line(pts, label, lx, ly, anchor="middle"):
        d = "M" + " L".join(f"{x} {y}" for x, y in pts)
        out.append(f'<path d="{d}" class="edge" marker-end="url(#ah)"/>')
        out.append(f'<text x="{lx}" y="{ly}" class="el" text-anchor="{anchor}">{e(label)}</text>')

    # row 1, left to right
    line([(190, 63), (298, 63)], "Prioritize", 245, 54)
    line([(470, 63), (578, 63)], "Start planning", 525, 54)
    line([(750, 63), (858, 63)], "Start recruiting", 805, 54)
    line([(945, 86), (945, 208)], "Launch interviews", 937, 152, "end")
    line([(860, 225), (752, 225)], "Analyze insights", 806, 216)
    line([(750, 243), (858, 243)], "Need more data", 806, 264)
    line([(630, 256), (530, 388)], "Hypothesis confirmed", 572, 330, "end")
    line([(700, 256), (800, 388)], "Hypothesis rejected", 758, 330, "start")
    line([(600, 86), (440, 208)], "Pause", 505, 132, "end")
    line([(470, 222), (632, 86)], "Resume", 580, 168, "start")
    # loop back from Done to Backlog
    out.append('<path d="M515 436 L515 470 M805 436 L805 470" class="edge"/>')
    line([(805, 470), (105, 470), (105, 88)], "New iteration", 113, 300, "start")

    for k, (x, y) in pos.items():
        out.append(f'<g class="node {cat[k]}"><rect x="{x}" y="{y}" width="{W}" height="{H}" rx="8"/>'
                   f'<text x="{x + W / 2}" y="{y + H / 2 + 5}" text-anchor="middle">{e(name[k].upper())}</text></g>')
    out.append("</svg>")
    return "".join(out)


def build(i):
    """Return {key: html} for language index i (0 = ru, 1 = en)."""
    name = {k: n for k, n, _, _, _ in STATUSES}
    cat = {k: c for k, _, c, _, _ in STATUSES}
    out = {"workflow": _svg(i)}

    def pill(k):
        return f'<span class="pill {cat[k]}">{e(name[k])}</span>'

    out["rows_status"] = "".join(f"<tr><td>{pill(k)}</td><td>{e(CAT[c][i])}</td><td>{e(m[i])}</td></tr>" for k, _, c, m, _ in STATUSES)
    rows = []
    for f, t, n, rule in TRANSITIONS:
        src = " / ".join(pill(x) for x in f.split("/"))
        rows.append(f"<tr><td>{src}</td><td>{pill(t)}</td><td><b>{e(n)}</b></td><td>{e(rule[i])}</td></tr>")
    out["rows_trans"] = "".join(rows)

    cards = []
    for hid, seg, belief, sol, metric, crit, method, (a, b, c) in sorted(HYPOTHESES, key=lambda h: -h[7][0] * h[7][1] * h[7][2]):
        dl = "".join(f"<dt>{e(T[k][i])}</dt><dd>{e(v[i])}</dd>" for k, v in
                     (("hy_belief", belief), ("hy_sol", sol), ("hy_metric", metric), ("hy_crit", crit), ("hy_method", method)))
        cards.append(f'<article class="hyp"><div class="hh"><span class="hid">{hid}</span><span class="seg">{e(seg[i])}</span>'
                     f'<span class="ice num" title="ICE = {a} × {b} × {c}">ICE {a * b * c}</span></div><dl>{dl}</dl></article>')
    out["hyps"] = "".join(cards)

    cols = []
    for s in BOARD:
        items = [t for t in TASKS if t[2] == s]
        body = "".join(f'<li><span class="tk">{k}</span><span class="tt">{e(txt[i])}</span><span class="th">{h}</span></li>' for k, h, _, txt in items)
        if not items:
            body = f'<li class="empty">{e(T["bl_empty"][i])}</li>'
        cols.append(f'<section class="col {cat[s]}"><h3>{e(name[s])} <span class="num">{len(items)}</span></h3><ul>{body}</ul></section>')
    out["board"] = "".join(cols)

    out["checks"] = "".join(f'<li><span class="n fix">✓</span><span><b>{e(a[i])}</b>{e(b[i])}</span></li>' for ok, a, b in CHECK)
    return out
